"""Human-readable evidence report; never convert partial validation into approval."""
import html,json
from deploy import ROOT
BASE=ROOT/'runs/w1_20261013_sender_validation'
NAME='W1 Sender-only 입력 충분성·안정성 검증_261013.html'

def table(head,rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def number(x,scale=1):return '—' if x is None else f'{x*scale:.2f}'
def main():
    q=json.loads((BASE/'qualification.json').read_text());results=q['results']
    cleanup=json.loads((BASE/'final_restoration.json').read_text()) if (BASE/'final_restoration.json').exists() else {'complete':False}
    c2=json.loads((BASE/'c2_readiness.json').read_text()) if (BASE/'c2_readiness.json').exists() else {'root_helper_prepared':False}
    s='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>W1 Sender-only 입력 충분성·안정성 검증</title><style>body{margin:0;background:#f3f6fa;color:#24364d;font:16px/1.75 system-ui,sans-serif}main{max-width:1180px;background:white;margin:24px auto;padding:30px}h1{font-size:28px}h2{margin-top:34px;border-bottom:1px solid #d4dfeb;padding-bottom:6px}.status{background:#fff3d7;border-left:4px solid #a97519;padding:18px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px;margin:16px 0}th,td{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #d4dfeb}th{background:#edf2f8}details{border:1px solid #d4dfeb;margin:16px 0}summary{padding:12px;cursor:pointer;font-weight:650;background:#f6f8fb}details>div{padding:16px}code{overflow-wrap:anywhere}i{font:italic 1.05em Cambria,serif}a{color:#175d99}@media(max-width:650px){main{padding:16px;margin:0}h1{font-size:24px}}</style></head><body><main><h1>W1 Sender-only 입력 충분성·안정성 검증</h1><p>2026-10-13 시작 캠페인 · 고정 프로파일의 독립 확인 · 수신 보조 모델은 유지</p><div class="status"><b>검증 실행과 자동 제어 승인은 구분한다.</b><p>송신 측 수동 관측 코드의 입력·계산·종료 동작을 실제 장비에서 시험했다. 아래 기준을 모두 통과하지 않은 상태에서는 <code>validated=false</code>를 유지한다. 이번 시험은 HTB를 적용하지 않는 shadow 관측이며, Adaptive의 성능 우위를 주장하지 않는다.</p></div>
<h2>1. 시험 구성과 미리 고정한 기준</h2><p>주 링크는 4번 → AX1500 공유기 → 5번이다. 두 단말 MT7921, 설치 커널 6.8.0-138, AP149번·80MHz를 사용했다. 송신 입력은 4번의 survey/station/native 계수와 같은 라디오의 rpmon 수동 프레임 관측이다. 5번의 계수·수신 처리량은 사후 검증용이며 제어 입력에 전달하지 않았다. 드라이버와 연구 DDS를 새로 설치하지 않았다.</p>
<p>본 시험 환경은 Wi-Fi 절전off, CPU performance, rmem_max·wmem_max 각각4MiB, iperf3 요청 소켓1MiB이다. 기존 값은 독립 복원 감시기에 저장했다. 송신 관측은 약200ms마다 읽으며 약3초 창을 사용한다. 창 누적2초 미만, 결측, 알 수 없는 PHY, 범위 이탈, 카운터 초기화, 다른 AP, 캡처 drop에서는 계산을 보류한다.</p>'''
    s+=table(['항목','판정 기준'],[['입력 충분성','유효 전송 조건의 정상 구간에서 estimated 비율≥95%'],['포착 byte 범위','정상 CRC 중계 body / 송신 station TX bytes =0.8~1.1'],['PHY 범위','AP→5 수동 관측1195~1205Mb/s; 알 수 없는 PHY byte와 capture drop 허용0'],['자기 부하 제거','다른 시험 트래픽이 없는 자기 부하에서 |β̂oth|의p95≤0.05'],['용량 예측','상한으로 자르기 전 예측과 실제 포화 UDP payload 처리량의 오차≤20%'],['종료 안정성','monitor 제거·noqueue 유지·일반 Wi-Fi ping/SSH 성공. 자동 재연결로 복구한 run은 안정성 통과로 세지 않음'],['프로파일','기존 frozen_sender_profile_v2를 그대로 복사. 계수 재교정·범위 완화 없음']])
    s+='''<details><summary>지표·단어·단위 설명</summary><div><p><b>Sender-only</b>: 수신 단말에서 읽은 통계 없이 송신 위치에서 관측한다. <b>shadow</b>: 계산은 기록하지만 실제 HTB 송신 상한을 바꾸지 않는다. <b>estimated</b>: 그 창의 입력 게이트를 통과해 추정치를 계산했다. <b>hold</b>: 해당 창은 계산을 승인하지 않았다. 성공 창 비율은 전송 성공률과 다르다.</p><p><b>body coverage</b>는 서로 다른 byte 계층을 교정 범위로 대조한 가시성 지표다. 정상 CRC로 관측한 중계 body bytes를 송신 iw station TX bytes로 나눈 값이며, 정확한 패킷 수신률·PPDU 포착률로 해석하지 않는다. CRC 오류 프레임은 잠정 진단에만 남기고 모델 입력에는 넣지 않았다. capture drop=0은 호스트 캡처 큐가 잃지 않았다는 뜻이며 공중의 모든 프레임을 보았다는 뜻이 아니다.</p><p><i>C₀</i>는 기존 교정의 UDP payload 처리량333.833Mb/s이다. 자기 부하0.2/0.5/0.8은 링크 속도를 줄인 조건이 아니라 이 값의 비율로 발행한 조건이다. <i>β̂oth</i>는 busy에서 고정 idle과 자기 중계 대리 비용을 뺀 다른 트래픽 점유 추정치다. 부호를 임의로0으로 잘라 감추지 않았다. <i>θ</i>는 station byte당 운용 서비스 비용이며 독립 물리 airtime이 아니다.</p><p>용량 비교는 <i>Ĉpayload=((1−β̂oth)/θ)×1400/mean_station_bytes</i>를 사용한다. UDP payload 단위로 변환해 수신 interval의 bytes/seconds와 대조한다. <i>α=0.9</i> 안전 계수, EMA, <i>0.9C₀</i> 상한을 거친 HTB 출력은 최대 용량 예측값으로 비교하지 않는다. iperf3 v3.9의 UDP 최종 sum.bytes가0인 자료가 있어 실제 수신 interval bytes를 합산했다.</p><p>암호화된 A-MSDU 내부 발신자는 이 경로로 읽지 못하므로 수신 MAC에 다른 대용량 발신자가 없다는 제한을 유지했다. 이 가정을 제거한 보편적 Sender-only 식별을 완료했다고 해석하지 않는다.</p></div></details><h2>2. 자기 부하·포화 입력 확인</h2><p>이 절과 B2는 iperf3 UDP payload1400B의 무선 입력 시험이다. 각 본 전송24초, 최초 포화 관측 시험만20초를 사용했다. 정상 구간은 송신 시작+4초부터 종료−2초까지다. 자기 부하와 포화는 별도 조건이며, 뒤의 DDS 시험은1MiB ROS 메시지를 사용한다. UDP 손실률은 별도 qualification.json에 남겨 계산 가능 창 비율과 혼동하지 않는다.</p>'''
    rows=[]
    for r in results:
        if r['tag'].startswith('b2'):continue
        name='포화·관측 켬' if r['tag']=='clean_nomonitor_r1' else '포화·관측 끔' if r['tag']=='capacity_nomonitor' else r['tag']
        rows.append([name,number(r['requested_Mbps']),number(r['receiver_goodput_Mbps']),number(r.get('success_fraction'),100)+'%' if r.get('success_fraction') is not None else '해당 없음',number(r.get('body_coverage_median'),100),number(r.get('beta_abs_p95')),str(r['receiver_udp_delta']['RcvbufErrors']),r.get('input_sufficiency_pass','해당 없음'),r.get('self_beta_pass','해당 없음'),r['lifecycle']['healthy_without_reconnect']])
    s+=table(['실험','요청Mb/s','수신Mb/s','계산 가능 창','coverage 중앙%','|β|p95','수신 버퍼 오류','입력 통과','자기 부하 통과','재연결 없는 종료'],rows)
    s+='<details><summary>예비 실패와 이번 환경 변경을 어떻게 해석하는가</summary><div><p>최초 baseline_nomonitor는 기본 커널 버퍼212992에서 수신 RcvbufErrors가37,788 증가해 RF 용량 검증에서 제외했다. self02_r1은 TCP 제어 연결 실패로 정상 부하가 성립하지 않았다. 이 예비 run의 최초 회수·종료 점검은 observer가 아직 실행 중일 때 이루어진 일정 오류가 있어 종료 안정성 근거로 사용하지 않는다. 기다림을 실제 관측 종료 시각 기준으로 수정했고, 종료 후 원자료는 final_4/5에 별도 보존했다.</p><p>준비 상태에서 얻은 결과는 CPU performance·절전off·확대 버퍼라는 명시적 조건에서의 결과다. 어느 설정 하나가 앞선 연결 실패의 유일한 원인이었다고 단정하지 않는다. clean_nomonitor_r1이라는 저장 이름에는 nomonitor가 있지만 실제 manifest의 monitor=true이고 송신 pcap/CSV가 있다. 표는 실제 실행 조건을 따라 관측 켬으로 표시했다.</p></div></details>'
    sat=[r for r in results if r['monitor'] and r['requested_Mbps']==0]
    s+='<h2>3. 교정에 사용하지 않은 용량 대조</h2>'
    s+=table(['실험','실제 payload Mb/s','예측 payload Mb/s','상대 오차%','입력 게이트','용량 통과'],[[r['tag'],number(r['receiver_goodput_Mbps']),number(r.get('raw_capacity_payload_Mbps_median')),number(r.get('capacity_relative_error'),100),r.get('input_sufficiency_pass'),r.get('capacity_pass',False)] for r in sat])
    s+='<p>실제 처리량이 옛 C₀보다 높아졌더라도 이번 결과에 맞춰 고정 비용이나 C₀를 다시 맞추지 않았다. 입력 게이트를 통과한 소수 창의 낮은 오차만으로 전체 run을 승인하지 않는다. 다른 트래픽 점유율이0인 자기 부하 run의 요청률은 포화 용량의 실측값으로 쓰지 않는다.</p><h2>4. B2·C2 입력 검증</h2>'
    b2=[r for r in results if r['tag'].startswith('b2')]
    s+=table(['B2 run','실제Mb/s','계산 가능 창%','coverage 중앙%','보류 사유','재연결 없는 종료'],[[r['tag'],number(r['receiver_goodput_Mbps']),number(r.get('success_fraction'),100),number(r.get('body_coverage_median'),100),json.dumps(r.get('hold_reasons'),ensure_ascii=False),r['lifecycle']['healthy_without_reconnect']] for r in b2])
    s+='<p>B2 첫 캡처의 CRC 정상 자기 중계 프레임에서 PHY1200.980Mb/s66,241개,1080.882Mb/s3,012개,960.784Mb/s1개가 읽혔으며 알 수 없는 PHY body bytes는0이었다. 따라서 이번 보류는 관측값이 전혀 없는 문제와 구분한다. 1195~1205Mb/s에 고정한 모델의 적용 범위를 벗어난 창은 사용할 수 없었다. 범위를 넓혀 통과 처리하지 않았으며, 여러 PHY 조건에서 운용 비용과 aggregation 보정을 독립 교정·검증해야 한다.</p>'
    s+='<details><summary>B2·C2 의미와 이번 수행 범위</summary><div><p><b>B2</b>: 같은149/80 채널의 다른 공유기 SR2에서12→10 경쟁 UDP를 발생시키고, 주 링크4→AX→5의 입력을 확인한다. 이번은75초 연속300Mb/s 요청 경쟁이며 원자료에서 실제 성립을 확인한다. proposal의2초 ON/2초 OFF 최종 성능 일정과 구분한다. <b>C2</b>: 주 링크와 같은 AX 공유기에 추가 경쟁 단말을 붙이는 조건이다. AP가 다르면 C2로 표시하지 않는다.</p>'
    s+='<p>10번의 사전 AP 전환 helper 준비 여부: '+str(c2.get('root_helper_prepared'))+'. 수행/건너뜀 내역은 c2_readiness.json에 기록했다. 사용자 퇴근 이후 수동 root 입력을 새로 요구하거나 sudo 권한을 확대하지 않는다.</p></div></details><h2>5. 1MiB DDS shadow와 오류 게이트</h2>'
    dds=[]
    for rmw in ['fastdds','cyclonedds']:
        p=ROOT/'runs/w1_20261013_sender_only'/('dds_validation_'+rmw)/'summary.json'
        if p.exists():
            r=json.loads(p.read_text());dds.append([rmw,r['planned'],r['published'],r['received'],r['sender_estimates'],number(r.get('success_fraction'),100),json.dumps(r.get('steady_hold_reasons',{}),ensure_ascii=False),str(r['runtime_valid'])])
    s+=table(['DDS','계획','발행','수신','전체 추정 창','정상 구간 계산 가능%','정상 구간 보류 사유','실제 런타임 해시'],dds)
    s+='<details><summary>DDS 시험 조건과 게이트 시험</summary><div><p>Fast DDS2.6.11·CycloneDDS0.10.5 고정 런타임, std_msgs/msg/UInt8MultiArray,1MiB, RELIABLE·KEEP_ALL·VOLATILE, 약0.2C₀/1MiB Hz, 정상 발행15초를 사용했다. DDS XML은 기존 생성기의 Static 결과다. Static은 C₀·RTT·메시지 크기 등으로 계산한 정적 설정이며 sweep 최적값을 모은 프로파일과 동일하지 않다. 여기서는 HTB를 적용하지 않았으므로 Fixed/Adaptive 성능 비교가 아니다. 라이브러리 closure는 실행 시 함께 로드되는 의존 라이브러리 묶음이며 실제 로드 경로·해시를 기존 기준과 대조했다. 종단 지연의 시계 오차 기준은 이번 시험에서 재승인하지 않았다.</p><p>56개 단위 시험으로 CRC 오류 배제, 캡처 손실·알 수 없는 PHY·중계 부족·암호화 소스 모호성의 보류, AP/boot/channel 변화·계수 초기화 배제, BlockAck 결측·다른 송신자 배제, 미승인 프로파일의 HTB 설치 거부와 정리 실패 시 복원 순서를 확인했다. 실제 RF 원자료로 입력 충분성을 대신하는 시험은 아니다.</p></div></details><h2>6. 종료·복원과 결론</h2>'
    s+='<p>최종 복원 검사 완료: <b>'+str(cleanup.get('complete'))+'</b>. 노트북별 원자료·sysctl·절전·CPU·qdisc·monitor·실험 프로세스·임시 유선 주소 점검은 final_restoration.json을 기준으로 한다. SSH IPQoS 수정은 이전에 확인한 연결 문제 해결 설정으로 유지한다. Receiver-assisted 코드와 모델은 보존했고 Sender-only 승인 플래그는 변경하지 않았다.</p>'
    s+='<details><summary>절전 전환과 최종 IPv4 접속 문제</summary><div><p>power_transition은 송신 절전on에서 시작해 관측기 진입 시off, 종료 시on으로 돌리는 진단이다. CPU performance와4MiB 커널 버퍼는 유지했다. 24초 전송·정상 구간 추정은 성공했고 monitor 삭제와noqueue·절전on도 확인됐지만, 종료 후5→4 일반 Wi-Fi SSH는 접속 시간 초과였다. 4→5 ping은 성공했다. 유선 관리에서 같은 AP를 재연결한 뒤 SSH가 복구됐으며, 재연결 없는 안정성 기준은 실패로 기록했다. 이 자료로 firmware의 정확한 원인을 확정하지 않는다.</p><p>최종 복원에서는4·5번 설정과 임시 유선 주소를 복원한 뒤5번 IPv4 ping/SSH가 불안정해 첫 사후 감사가 실패했다. 설정 복원 자체의 성공 영수증은 이미 회수했다. 기존 Wi-Fi IPv6 link-local SSH로4·5번을 읽고,12·10번은 기존SR2 경로에서 읽어 네 장비의 실제 최종 상태를 확인했다. 새로운 인증 키나 일반 root 권한을 부여하지 않았다. IPv6 접속이 가능하다는 사실은 IPv4 문제의 원인을 해결했다는 뜻이 아니다.</p><p>절전off를 고정한 자기 부하·포화·B2·DDS 반복의 종료는 재연결 없이 성공했지만, 절전 전환과 원상복원 이후 네트워크의 보편 안정성은 승인하지 않았다. 시험 시간이 짧아 장시간 안정성도 검증했다고 표시하지 않는다.</p></div></details>'
    s+='<p>현재 증거는 시험한 AP·드라이버·PHY·단독 수신자·짧은 반복 시간 범위에 한정된다. 입력 충분성, 자기 부하 제거, 독립 용량 오차, C2, 실제 DDS 입력 조건을 모두 충족해야 자동 제어 승인 여부를 다시 판단할 수 있다. 정확한 전체 HE/PPDU airtime이나 보편적 물리 O를 새로 식별한 결과가 아니다.</p>'
    s+='<p><b>다음 작업:</b> 관측된1081Mb/s 등 여러 하향 PHY에서 aggregation·운용 비용의 적용성을 별도 교정하고 고정 후 재검증한다. 용량 오차19.74%/20.65%의 경계 결과와 Fast DDS 정상 구간73.33%를 유지하며, 입력 범위를 단순히 넓혀 승인하지 않는다. 절전 전환·IPv4 경로의 원인을 분리해 종료 안정성을 해결한다. C2 준비가 가능해지는 시점에 같은 AP 경쟁 검증을 수행한다. 기존 Receiver-assisted 결과를 Sender-only 결과로 대체하지 않는다.</p><p>이 파일명261013은 캠페인 시작일이다. 측정과 복원은10/14까지 이어졌으며 실제 wall/monotonic 시각과 종료UTC는 preservation.json 및 각run 원자료에 보존했다.</p>'
    s+='<p>'+ ' · '.join('<a href="../../../ROSPacer/runs/w1_20261013_sender_validation/'+x+'">'+y+'</a>' for x,y in [('protocol.json','고정한 절차'),('qualification.json','전체 판정'),('final_restoration.json','종료·복원'),('evidence_sha256.json','자료 해시')])+'</p></main></body></html>'
    dest=ROOT.parent/'html 파일 모음/결과/W1 실험결과'/NAME;dest.write_text(s,encoding='utf8')
